import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { hogFlowsReputationRetrieve } from 'products/workflows/frontend/generated/api'
import type { WorkflowEmailSendingRatesApi } from 'products/workflows/frontend/generated/api.schemas'

import { reputationResponseLogic } from './reputationResponseLogic'

interface WorkflowSearchResults {
    search: string
    workflows: readonly WorkflowEmailSendingRatesApi[]
    failed: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reputationWorkflowSearchLogicValues {
    currentProjectId: number | null // projectLogic
    reputationResponseLoading: boolean // reputationResponseLogic
    workflowSnapshots: readonly WorkflowEmailSendingRatesApi[] // reputationResponseLogic
    currentSearchResults: WorkflowSearchResults | null
    search: string
    searchTerm: string
    tableLoading: boolean
    tableWorkflows: readonly WorkflowEmailSendingRatesApi[]
    workflowSearchFailed: boolean
    workflowSearchResults: WorkflowSearchResults | null
    workflowSearchResultsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reputationWorkflowSearchLogicActions {
    searchWorkflows: () => {
        value: true
    }
    searchWorkflowsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    searchWorkflowsSuccess: (
        workflowSearchResults: WorkflowSearchResults | null,
        payload?: {
            value: true
        }
    ) => {
        workflowSearchResults: WorkflowSearchResults | null
        payload?: {
            value: true
        }
    }
    setSearch: (search: string) => {
        search: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface reputationWorkflowSearchLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        searchTerm: (search: string) => string
        currentSearchResults: (
            searchTerm: string,
            workflowSearchResults: WorkflowSearchResults | null
        ) => WorkflowSearchResults | null
        tableWorkflows: (
            searchTerm: string,
            workflowSnapshots: readonly WorkflowEmailSendingRatesApi[],
            currentSearchResults: WorkflowSearchResults | null
        ) => readonly WorkflowEmailSendingRatesApi[]
        workflowSearchFailed: (currentSearchResults: WorkflowSearchResults | null) => boolean
        tableLoading: (
            reputationResponseLoading: boolean,
            searchTerm: string,
            currentSearchResults: WorkflowSearchResults | null
        ) => boolean
    }
}

export type reputationWorkflowSearchLogicType = MakeLogicType<
    reputationWorkflowSearchLogicValues,
    reputationWorkflowSearchLogicActions,
    Record<string, any>,
    reputationWorkflowSearchLogicMeta
>

export const reputationWorkflowSearchLogic = kea<reputationWorkflowSearchLogicType>([
    path(['products', 'workflows', 'frontend', 'Workflows', 'Reputation', 'reputationWorkflowSearchLogic']),
    connect(() => ({
        values: [
            projectLogic,
            ['currentProjectId'],
            reputationResponseLogic,
            ['workflowSnapshots', 'reputationResponseLoading'],
        ],
    })),
    actions({
        // Declared here (as well as auto-created by the loader) so kea-typegen sees a payload-less
        // action; without this, TS types the first loader arg as required and callers fail typecheck.
        searchWorkflows: true,
        setSearch: (search: string) => ({ search }),
    }),
    loaders(({ values }) => ({
        workflowSearchResults: [
            null as WorkflowSearchResults | null,
            {
                searchWorkflows: async (_, breakpoint): Promise<WorkflowSearchResults | null> => {
                    const search = values.searchTerm
                    if (!search || !values.currentProjectId) {
                        return null
                    }
                    try {
                        const response = await hogFlowsReputationRetrieve(String(values.currentProjectId), {
                            search,
                        })
                        breakpoint()
                        return { search, workflows: response.workflows, failed: false }
                    } catch {
                        breakpoint()
                        // The table says the search failed, which a toast alone does not do for a
                        // network error, and the rows of the previous term must not stay on screen.
                        return { search, workflows: [], failed: true }
                    }
                },
            },
        ],
    })),
    reducers({
        search: [
            '',
            {
                setSearch: (_, { search }) => search,
            },
        ],
    }),
    listeners(({ actions }) => ({
        // Search filters server-side (the response is capped to the worst 50 workflows), so each
        // keystroke needs a reload, debounced here and made stale-safe by the loader's breakpoint.
        setSearch: async (_, breakpoint) => {
            await breakpoint(250)
            actions.searchWorkflows()
        },
    })),
    selectors({
        searchTerm: [(s) => [s.search], (search: string): string => search.trim()],
        // The search starts after a debounce, so the typed term runs ahead of the loader. Results
        // for an older term must not answer the term on screen.
        currentSearchResults: [
            (s) => [s.searchTerm, s.workflowSearchResults],
            (searchTerm: string, results: WorkflowSearchResults | null): WorkflowSearchResults | null =>
                !!searchTerm && results?.search === searchTerm ? results : null,
        ],
        tableWorkflows: [
            (s) => [s.searchTerm, s.workflowSnapshots, s.currentSearchResults],
            (
                searchTerm: string,
                workflowSnapshots: readonly WorkflowEmailSendingRatesApi[],
                results: WorkflowSearchResults | null
            ): readonly WorkflowEmailSendingRatesApi[] => (searchTerm ? (results?.workflows ?? []) : workflowSnapshots),
        ],
        workflowSearchFailed: [
            (s) => [s.currentSearchResults],
            (results: WorkflowSearchResults | null): boolean => !!results?.failed,
        ],
        tableLoading: [
            (s) => [s.reputationResponseLoading, s.searchTerm, s.currentSearchResults],
            (reputationResponseLoading: boolean, searchTerm: string, results: WorkflowSearchResults | null): boolean =>
                reputationResponseLoading || (!!searchTerm && !results),
        ],
    }),
])
